   print(json.dumps({'contentParity':'passed','canvasCreateSaveReload':True,'dirtyNavigationNoSave':True,'conflictRetainsEdits':True,'reviewResolve':True,'attachmentDownload':True,'summaryManualOnly':True,'draftSurvivesCollapseAndNavigation':True,'mobileWidth':393,'errors':errors}));await browser.close()
